import { test } from "node:test";
import assert from "node:assert/strict";
import { setTimeout as sleep } from "node:timers/promises";
import { quoteCart, type PriceSource } from "../src/pricing/quoteCart.ts";
import { cartTotal } from "../src/pricing/cartTotal.ts";
import { CachedPriceSource } from "../src/pricing/priceCache.ts";
import { checkoutSummary } from "../src/pricing/checkout.ts";

// On CI the price service sometimes answers out of order. These fakes pin the
// latencies so that ordering happens on every run instead of now and then.
const PRICES: Record<string, number> = { mug: 1200, tee: 2500, cap: 1800, pin: 300 };
const LATENCY_MS: Record<string, number> = { mug: 40, tee: 5, cap: 20, pin: 1 };

function fakeSource(failing: string[] = []): PriceSource & { maxInFlight: number; calls: string[] } {
    let inFlight = 0;
    const source = {
        maxInFlight: 0,
        calls: [] as string[],
        async fetchPriceCents(sku: string) {
            source.calls.push(sku);
            inFlight++;
            source.maxInFlight = Math.max(source.maxInFlight, inFlight);
            try {
                await sleep(LATENCY_MS[sku] ?? 1);
                if (failing.includes(sku)) throw new Error(`price service timeout for ${sku}`);
                return PRICES[sku];
            } finally {
                inFlight--;
            }
        },
    };
    return source;
}

test("quotes come back in the order the SKUs were given", async () => {
    const quotes = await quoteCart(["mug", "tee", "cap", "pin"], fakeSource());
    console.log("quote order:", quotes.map((q) => q.sku).join(", "));
    assert.deepEqual(quotes.map((q) => q.sku), ["mug", "tee", "cap", "pin"]);
});

test("a failed lookup is reported in its own position", async () => {
    const quotes = await quoteCart(["mug", "tee", "cap"], fakeSource(["tee"]));
    assert.deepEqual(quotes.map((q) => q.priceCents), [1200, null, 1800]);
});

test("cart total multiplies each line by its own price", async () => {
    const total = await cartTotal([{ sku: "mug", quantity: 1 }, { sku: "pin", quantity: 10 }], fakeSource());
    assert.deepEqual(total, { totalCents: 1200 + 3000, unpriced: [] });
});

test("never more than `concurrency` requests in flight; an empty cart makes none", async () => {
    const source = fakeSource();
    await quoteCart(["mug", "tee", "cap", "pin", "mug", "tee", "cap", "pin"], source, 2);
    assert.equal(source.maxInFlight, 2);
    assert.deepEqual(await quoteCart([], source), []);
});

test("the price cache serves repeats within the TTL and refetches after", async () => {
    const inner = fakeSource();
    let now = 1_000;
    const cached = new CachedPriceSource(inner, 60_000, () => now);
    assert.equal(await cached.fetchPriceCents("pin"), 300);
    now += 30_000;
    assert.equal(await cached.fetchPriceCents("pin"), 300);
    now += 31_000;
    assert.equal(await cached.fetchPriceCents("pin"), 300);
    assert.deepEqual(inner.calls, ["pin", "pin"]);
});

test("concurrent lookups of one SKU share a request, and failures aren't cached", async () => {
    const inner = fakeSource(["cap"]);
    const cached = new CachedPriceSource(inner, 60_000, () => 0);
    await Promise.all([cached.fetchPriceCents("mug"), cached.fetchPriceCents("mug"), cached.fetchPriceCents("mug")]);
    await assert.rejects(cached.fetchPriceCents("cap"));
    await assert.rejects(cached.fetchPriceCents("cap"));
    assert.deepEqual(inner.calls, ["mug", "cap", "cap"]);
});

test("checkout charges the right total, tax included", async () => {
    const summary = await checkoutSummary(
        [{ sku: "mug", quantity: 2 }, { sku: "tee", quantity: 1 }, { sku: "pin", quantity: 4 }],
        fakeSource(),
        825, // 8.25%
    );
    assert.deepEqual(summary, { ok: true, subtotalCents: 6100, taxCents: 503, totalCents: 6603 });
});

test("checkout is blocked while an item can't be priced, and for an empty cart", async () => {
    assert.deepEqual(
        await checkoutSummary([{ sku: "mug", quantity: 1 }, { sku: "cap", quantity: 2 }], fakeSource(["cap"]), 825),
        { ok: false, reason: "unpriced_items", skus: ["cap"] },
    );
    assert.deepEqual(await checkoutSummary([{ sku: "mug", quantity: 0 }], fakeSource(), 825), { ok: false, reason: "empty_cart", skus: [] });
});
